html.script:
//
document.addEventListener('DOMContentLoaded', function () {

  var searchButton = document.getElementById('searchButton');
  var searchPanel = document.getElementById('searchPanel');
  var menuButton = document.getElementById('menuButton');
  var mobileMenu = document.getElementById('mobileMenu');

  if (!searchButton || !searchPanel || !menuButton || !mobileMenu) {
    return;
  }

  searchButton.addEventListener('click', function () {

    var open = searchPanel.classList.toggle('active');

    mobileMenu.classList.remove('active');
    menuButton.setAttribute('aria-expanded', 'false');

    var icon = searchButton.querySelector('i');

    if (icon) {
      icon.classList.toggle('fa-xmark', open);
      icon.classList.toggle('fa-magnifying-glass', !open);
    }

    if (open) {

      var input = searchPanel.querySelector('.search-input');

      if (input) {
        setTimeout(function () {
          input.focus();
        }, 150);
      }

    }

  });

  menuButton.addEventListener('click', function () {

    var open = mobileMenu.classList.toggle('active');

    searchPanel.classList.remove('active');

    menuButton.setAttribute(
      'aria-expanded',
      open ? 'true' : 'false'
    );

    var icon = menuButton.querySelector('i');

    if (icon) {
      icon.classList.toggle('fa-xmark', open);
      icon.classList.toggle('fa-bars', !open);
    }

    var searchIcon = searchButton.querySelector('i');

    if (searchIcon) {
      searchIcon.classList.remove('fa-xmark');
      searchIcon.classList.add('fa-magnifying-glass');
    }

  });

  document.addEventListener('keydown', function (e) {

    if (e.key === 'Escape') {

      searchPanel.classList.remove('active');
      mobileMenu.classList.remove('active');

      var searchIcon = searchButton.querySelector('i');
      var menuIcon = menuButton.querySelector('i');

      if (searchIcon) {
        searchIcon.className =
          'fa-solid fa-magnifying-glass';
      }

      if (menuIcon) {
        menuIcon.className =
          'fa-solid fa-bars';
      }

      menuButton.setAttribute(
        'aria-expanded',
        'false'
      );

    }

  });

});
//

b:if.script:
//
(function () {
  var raiz = document.currentScript && document.currentScript.parentNode;

  if (!raiz || !window.matchMedia || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    return;
  }

  // Oculta el estado inicial antes del primer pintado
  raiz.classList.add('ciad-prep');

  var iniciado = false;

  function iniciar() {
    if (iniciado) {
      return;
    }

    iniciado = true;
    raiz.classList.add('ciad-listo');
  }

  // Espera a que las tres letras estén decodificadas para que la entrada no se corte
  function esperarLetras() {
    var imagenes = raiz.querySelectorAll('.ciad-letra img');
    var pendientes = [];

    for (var i = 0; i < imagenes.length; i++) {
      pendientes.push(imagenes[i].decode ? imagenes[i].decode().catch(function () {}) : Promise.resolve());
    }

    var limite = new Promise(function (resolver) { setTimeout(resolver, 2500); });

    Promise.race([Promise.all(pendientes), limite]).then(function () {
      requestAnimationFrame(iniciar);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', esperarLetras);
  } else {
    esperarLetras();
  }

  // Seguro: si algo falla, el contenido aparece igual
  setTimeout(iniciar, 4000);
})();
//

//
// Los textos de la portada se editan en el Panel CIAD (página /p/inicio.html) y aquí se copian.
// El HTML de la página se lee con DOMParser (inerte: no carga imágenes ni ejecuta nada).
(function () {
  fetch('/feeds/pages/default/7758592480728629486?alt=json')
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (d) {
      var html = d && d.entry && d.entry.content && d.entry.content.$t;
      if (!html) return;
      var pagina = new DOMParser().parseFromString(html, 'text/html');
      document.querySelectorAll('.contenedor-inicio [data-editable], .seccion-recientes:not(.vista-notas) [data-editable]').forEach(function (el) {
        var origen = pagina.querySelector('[data-editable="' + CSS.escape(el.getAttribute('data-editable')) + '"]');
        if (origen && origen.textContent.trim()) el.innerHTML = origen.innerHTML;
      });
    })
    .catch(function () {});
})();
//

//
(function () {

  var MAXIMO_RECIENTES = 3;
  // shortcut: máx. 150 notas por sección (límite de una consulta al feed); paginar si alguna sección pasa de 150
  var MAXIMO_POR_COMPONENTE = 150;
  var IMAGEN_GENERICA = "data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 800 500%27%3E%3Crect width=%27800%27 height=%27500%27 fill=%27%23e6f2ec%27/%3E%3Cpath d=%27M0 500L800 290V500z%27 fill=%27%2300723f%27 opacity=%27.14%27/%3E%3C/svg%3E";

  function rutaFeedRecientes(etiqueta, maximo) {
    return '/feeds/posts/default' +
      (etiqueta ? '/-/' + encodeURIComponent(etiqueta) : '') +
      '?alt=json&orderby=published&max-results=' +
      (maximo || (etiqueta ? MAXIMO_POR_COMPONENTE : MAXIMO_RECIENTES));
  }

  function quitarHtml(texto) {
    var caja = document.createElement('div');
    caja.innerHTML = texto || '';

    return (caja.textContent || '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function recortar(texto, limite) {
    if (!texto || texto.length <= limite) {
      return texto || '';
    }

    return texto
      .substring(0, limite)
      .replace(/\s+\S*$/, '') + '…';
  }

  function obtenerEnlace(entrada) {
    var enlaces = entrada.link || [];

    for (var i = 0; i < enlaces.length; i++) {
      if (enlaces[i].rel === 'alternate') {
        return enlaces[i].href;
      }
    }

    return '#';
  }

  function obtenerImagen(entrada, indice) {
    // Panel CIAD (imagenCiad): la imagen de las tarjetas de la nota (o la principal) va antes que la miniatura de Blogger
    var contenidoCiad = entrada.content ? entrada.content.$t || '' : '';
    var imagenCiad = contenidoCiad.match(/\x3cimg[^>]*class="articulo-tarjeta"[^>]*src="([^"]+)"/) || contenidoCiad.match(/\x3cfigure class="articulo-portada"[^>]*>\x3cimg[^>]*src="([^"]+)"/);
    if (imagenCiad) { return imagenCiad[1].replace(/\x26amp;/g, '\x26'); }

    if (
      entrada.media$thumbnail &&
      entrada.media$thumbnail.url
    ) {
      return entrada.media$thumbnail.url
        .replace(/\/s72-c\//, '/w900-h506-c/');
    }

    var contenido =
      (entrada.content && entrada.content.$t) ||
      (entrada.summary && entrada.summary.$t) ||
      '';

    var caja = document.createElement('div');
    caja.innerHTML = contenido;

    var imagen = caja.querySelector('img');

    if (imagen && imagen.src) {
      return imagen.src;
    }

    return IMAGEN_GENERICA;
  }

  // Texto de la entrada sin la ficha del autor ni estilos, con espacios entre bloques
  function textoResumen(html) {
    var caja = document.createElement('div');
    caja.innerHTML = html || '';
    caja.querySelectorAll('style, script, .articulo-ficha, .articulo-lectura').forEach(function (el) { el.remove(); });
    caja.querySelectorAll('p, h1, h2, h3, h4, li, div, br').forEach(function (el) { el.insertAdjacentText('afterend', ' '); });
    return (caja.textContent || '').replace(/\s+/g, ' ').trim();
  }

  function obtenerResumen(entrada) {
    var contenido =
      (entrada.summary && entrada.summary.$t) ||
      (entrada.content && entrada.content.$t) ||
      '';

    return recortar(
      textoResumen(contenido),
      155
    );
  }

  function formatearFecha(iso) {
    var fecha = new Date(iso);

    if (isNaN(fecha)) {
      return '';
    }

    return fecha.toLocaleDateString(
      'es-MX',
      {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      }
    );
  }

  function crearTarjeta(entrada, indice) {

    var enlace = obtenerEnlace(entrada);
    var titulo = quitarHtml(
      entrada.title ? entrada.title.$t : 'Publicación'
    );

    var articulo = document.createElement('article');
    articulo.className = 'tarjeta-reciente';

    var enlaceImagen = document.createElement('a');
    enlaceImagen.className = 'enlace-imagen-reciente';
    enlaceImagen.href = enlace;

    var imagen = document.createElement('img');
    imagen.className = 'imagen-reciente';
    imagen.src = obtenerImagen(entrada, indice);
    imagen.alt = '';
    imagen.loading = 'lazy';
    imagen.addEventListener('error', function () {
      if (this.dataset.fallbackAplicado === '1') {
        return;
      }

      this.dataset.fallbackAplicado = '1';
      this.src = IMAGEN_GENERICA;
    });

    enlaceImagen.appendChild(imagen);

    var contenido = document.createElement('div');
    contenido.className = 'contenido-reciente';

    var fecha = document.createElement('p');
    fecha.className = 'fecha-reciente';
    fecha.textContent = formatearFecha(
      entrada.published ? entrada.published.$t : ''
    );
    // Minutos de lectura (párrafo .articulo-lectura de la nota): insignia a la derecha de la fecha
    var lectura = ((entrada.content && entrada.content.$t) || '').match(/class="articulo-lectura"[^>]*>[^<]*?(\d+)\s*min/);
    if (lectura) {
      var insignia = document.createElement('span');
      insignia.className = 'lectura-tarjeta';
      insignia.title = 'Lectura de ' + lectura[1] + ' min';
      insignia.innerHTML = '<i class="fa-regular fa-clock" aria-hidden="true"></i> ' + lectura[1] + ' min';
      fecha.appendChild(insignia);
    }

    var h3 = document.createElement('h3');
    h3.className = 'titulo-reciente';

    var enlaceTitulo = document.createElement('a');
    enlaceTitulo.href = enlace;
    enlaceTitulo.textContent = titulo;
    h3.appendChild(enlaceTitulo);

    var resumen = document.createElement('p');
    resumen.className = 'resumen-reciente';
    resumen.textContent = obtenerResumen(entrada);

    var leer = document.createElement('a');
    leer.className = 'leer-reciente';
    leer.href = enlace;
    leer.textContent = 'Leer nota';

    contenido.appendChild(fecha);
    contenido.appendChild(h3);
    contenido.appendChild(resumen);
    contenido.appendChild(leer);

    articulo.appendChild(enlaceImagen);
    articulo.appendChild(contenido);

    return articulo;
  }

  function cargarRecientes(lista, etiqueta, maximo) {

    var estado = lista.querySelector('.estado-recientes');

    fetch(rutaFeedRecientes(etiqueta, maximo))
      .then(function (respuesta) {

        if (!respuesta.ok) {
          throw new Error('Respuesta no válida');
        }

        return respuesta.json();
      })
      .then(function (datos) {

        var entradas =
          (datos.feed && datos.feed.entry) || [];

        lista.innerHTML = '';

        if (!entradas.length) {
          var vacio = document.createElement('p');
          vacio.className = 'estado-recientes';
          vacio.textContent = etiqueta
            ? 'Aún no hay notas en esta categoría.'
            : 'Aún no hay notas publicadas.';
          lista.appendChild(vacio);
          return;
        }

        for (var i = 0; i < entradas.length; i++) {
          lista.appendChild(
            crearTarjeta(entradas[i], i + 1)
          );
        }
      })
      .catch(function (error) {

        console.error(
          'CIAD · Notas recientes del Inicio:',
          error
        );

        if (estado) {
          estado.textContent =
            'No fue posible cargar las notas recientes en este momento.';
        }
      });
  }

  document.querySelectorAll('#lista-recientes-home, .lista-recientes[data-etiqueta]').forEach(function (lista) {
    cargarRecientes(lista, lista.getAttribute('data-etiqueta'), lista.getAttribute('data-maximo'));
  });

})();
//

section.script:
//
import {
  collection, addDoc, query, where, getDocs, getDoc, doc, serverTimestamp
} from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-firestore.js';

const seccion = document.getElementById('comments');
const POST = {
  id: String(seccion.dataset.postId || ''),
  url: seccion.dataset.postUrl || location.href.split('#')[0],
  titulo: seccion.dataset.postTitulo || document.title
};
const MAXIMO_MOSTRADOS = 50;

const $ = (id) => document.getElementById(id);
const mensaje = $('comentarios-mensaje');
const sinSesion = $('comentarios-sin-sesion');
const formulario = $('comentarios-formulario');
const areaTexto = $('comentarios-texto');
const botonEnviar = $('comentarios-enviar');

let db = null;
let usuario = null;
let enviando = false;

// DEF-009: evita comentarios repetidos o enviados muy seguido
const ESPERA_ENTRE_COMENTARIOS_MS = 60000;
let textosPropios = [];   // textos que el usuario ya envió en esta entrada
let ultimoEnvio = 0;

function normalizarTexto(t) {
  return String(t || '').toLowerCase().replace(/\s+/g, ' ').trim();
}

function avisar(texto, tipo) {
  mensaje.textContent = texto || '';
  mensaje.className = 'mensaje-caja' + (tipo ? ' ' + tipo : '');
  mensaje.hidden = !texto;
}

function fecha(valor) {
  const d = valor && valor.toDate ? valor.toDate() : null;
  return d ? d.toLocaleDateString('es-MX', { day: 'numeric', month: 'long', year: 'numeric' }) : '';
}

function avatar(foto, nombre) {
  if (foto) {
    const img = document.createElement('img');
    img.className = 'avatar';
    img.src = foto;
    img.alt = '';
    img.referrerPolicy = 'no-referrer';
    return img;
  }
  const span = document.createElement('span');
  span.className = 'avatar';
  span.textContent = (nombre || '?').trim().charAt(0).toUpperCase();
  return span;
}

function crearComentario(c, propio) {
  const art = document.createElement('article');
  art.className = 'comentario';
  art.appendChild(avatar(c.foto, c.nombre));

  const cuerpo = document.createElement('div');
  const cabecera = document.createElement('div');
  cabecera.className = 'comentario-cabecera';

  const nombre = document.createElement('span');
  nombre.className = 'comentario-nombre';
  nombre.textContent = c.nombre || 'Lector';
  cabecera.appendChild(nombre);

  const cuando = document.createElement('span');
  cuando.className = 'comentario-fecha';
  cuando.textContent = fecha(c.creado);
  cabecera.appendChild(cuando);

  if (propio) {
    const estado = document.createElement('span');
    estado.className = 'estado-propio ' + c.estado;
    estado.textContent = c.estado === 'pendiente' ? 'En revisión' : 'No publicado';
    cabecera.appendChild(estado);
  }

  const texto = document.createElement('p');
  texto.className = 'comentario-texto';
  texto.textContent = c.texto;

  cuerpo.appendChild(cabecera);
  cuerpo.appendChild(texto);

  if (propio && c.estado === 'rechazado' && c.notaModerador) {
    const nota = document.createElement('div');
    nota.className = 'nota-moderador';
    nota.textContent = 'Nota del equipo editorial: ' + c.notaModerador;
    cuerpo.appendChild(nota);
  }

  art.appendChild(cuerpo);
  return art;
}

function ordenarRecientes(lista) {
  return lista.sort((a, b) => ((b.creado && b.creado.toMillis ? b.creado.toMillis() : 0) - (a.creado && a.creado.toMillis ? a.creado.toMillis() : 0)));
}

async function cargarPublicados() {
  const lista = $('comentarios-lista');
  try {
    const q = query(collection(db, 'comentarios'),
      where('postId', '==', POST.id),
      where('estado', '==', 'publicado'));
    const res = await getDocs(q);
    const comentarios = ordenarRecientes(res.docs.map((d) => d.data())).slice(0, MAXIMO_MOSTRADOS);

    lista.innerHTML = '';
    $('comentarios-total').textContent = comentarios.length ? '(' + comentarios.length + ')' : '';

    if (!comentarios.length) {
      const vacio = document.createElement('p');
      vacio.className = 'sin-comentarios';
      vacio.textContent = 'Aún no hay comentarios. Sé el primero en comentar.';
      lista.appendChild(vacio);
      return;
    }
    comentarios.forEach((c) => lista.appendChild(crearComentario(c, false)));
  } catch (err) {
    console.error('Comentarios CIAD:', err);
    lista.innerHTML = '<p class="sin-comentarios">No fue posible cargar los comentarios.</p>';
  }
}

async function cargarPropios() {
  const bloque = $('comentarios-propios');
  const lista = $('comentarios-propios-lista');
  if (!usuario) { bloque.hidden = true; return; }

  try {
    const q = query(collection(db, 'comentarios'),
      where('postId', '==', POST.id),
      where('uid', '==', usuario.uid));
    const res = await getDocs(q);
    const todos = res.docs.map((d) => d.data());
    textosPropios = todos.map((c) => normalizarTexto(c.texto));
    const recientes = todos.map((c) => (c.creado && c.creado.toMillis ? c.creado.toMillis() : 0));
    ultimoEnvio = Math.max(ultimoEnvio, ...recientes, 0);
    const propios = ordenarRecientes(todos.filter((c) => c.estado !== 'publicado'));

    lista.innerHTML = '';
    propios.forEach((c) => lista.appendChild(crearComentario(c, true)));
    bloque.hidden = !propios.length;
  } catch (err) {
    console.error('Comentarios CIAD (propios):', err);
    bloque.hidden = true;
  }
}

async function estaBloqueado() {
  try {
    const d = await getDoc(doc(db, 'bloqueados', usuario.uid));
    return d.exists();
  } catch (err) {
    return false;
  }
}

async function aplicarSesion(u) {
  usuario = u && u.uid ? u : null;

  if (!usuario) {
    formulario.hidden = true;
    sinSesion.hidden = false;
    avisar('');
    $('comentarios-propios').hidden = true;
    return;
  }

  sinSesion.hidden = true;

  if (await estaBloqueado()) {
    formulario.hidden = true;
    avisar('Tu cuenta no puede publicar comentarios en este blog.', 'error');
    return;
  }

  const autor = $('comentarios-autor');
  autor.innerHTML = '';
  autor.appendChild(avatar(usuario.photoURL, usuario.displayName));
  autor.appendChild(document.createTextNode(usuario.displayName || usuario.email));

  avisar('');
  formulario.hidden = false;
  cargarPropios();
}

areaTexto.addEventListener('input', () => {
  $('comentarios-contador').textContent = areaTexto.value.length;
});

botonEnviar.addEventListener('click', async () => {
  if (enviando || !usuario) return;
  const texto = areaTexto.value.trim();

  if (texto.length < 2) {
    avisar('Escribe tu comentario antes de enviarlo.', 'error');
    areaTexto.focus();
    return;
  }

  if (textosPropios.indexOf(normalizarTexto(texto)) !== -1) {
    avisar('Ya enviaste este comentario en esta entrada.', 'error');
    return;
  }

  const faltan = ultimoEnvio + ESPERA_ENTRE_COMENTARIOS_MS - Date.now();
  if (faltan > 0) {
    avisar('Espera ' + Math.ceil(faltan / 1000) + ' segundos antes de enviar otro comentario.', 'error');
    return;
  }

  enviando = true;
  botonEnviar.disabled = true;
  botonEnviar.textContent = 'Enviando…';

  try {
    await addDoc(collection(db, 'comentarios'), {
      postId: POST.id,
      postUrl: POST.url,
      postTitulo: POST.titulo,
      uid: usuario.uid,
      nombre: usuario.displayName || usuario.email,
      foto: usuario.photoURL || '',
      texto: texto,
      estado: 'pendiente',
      creado: serverTimestamp()
    });
    textosPropios.push(normalizarTexto(texto));
    ultimoEnvio = Date.now();
    areaTexto.value = '';
    $('comentarios-contador').textContent = '0';
    avisar('¡Gracias! Tu comentario fue enviado y aparecerá cuando el equipo del CIAD lo apruebe.', 'exito');
    cargarPropios();
  } catch (err) {
    console.error('Comentarios CIAD (envío):', err);
    avisar(err && err.code === 'permission-denied'
      ? 'No se pudo enviar tu comentario. Revisa que no supere los 1000 caracteres.'
      : 'No se pudo enviar tu comentario. Intenta de nuevo en un momento.', 'error');
  } finally {
    enviando = false;
    botonEnviar.disabled = false;
    botonEnviar.textContent = 'Enviar comentario';
  }
});

$('comentarios-iniciar').addEventListener('click', () => {
  try {
    if (window.google && google.accounts && google.accounts.id) google.accounts.id.prompt();
  } catch (e) {  }
  window.scrollTo({ top: 0, behavior: 'smooth' });
});

function esperarFirebase() {
  return new Promise((resolver, rechazar) => {
    let intentos = 0;
    const revisar = setInterval(() => {
      intentos++;
      if (window.CIADFirebase && window.CIADFirebase.db) {
        clearInterval(revisar);
        resolver(window.CIADFirebase);
      } else if (intentos >= 40) {
        clearInterval(revisar);
        rechazar(new Error('Firebase no cargó'));
      }
    }, 250);
  });
}

window.addEventListener('ciad-auth-changed', (e) => {
  if (db) aplicarSesion(e.detail && e.detail.user);
});

try {
  const fb = await esperarFirebase();
  db = fb.db;
  cargarPublicados();
  aplicarSesion(fb.getCurrentUser ? fb.getCurrentUser() : null);
} catch (err) {
  console.error('Comentarios CIAD:', err);
  avisar('Los comentarios no están disponibles en este momento.', 'error');
}
//

body.script:
//
import { initializeApp } from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-app.js';
import {
  getAuth,
  GoogleAuthProvider,
  signInWithCredential,
  signOut,
  onAuthStateChanged,
  setPersistence,
  browserLocalPersistence
} from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-auth.js';
import {
  getFirestore,
  doc,
  getDoc,
  setDoc,
  updateDoc,
  serverTimestamp
} from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-firestore.js';

const firebaseConfig = {
    apiKey: "<FIREBASE_API_KEY>",
    authDomain: "ciad-blog-2026.firebaseapp.com",
    projectId: "ciad-blog-2026",
    storageBucket: "ciad-blog-2026.firebasestorage.app",
    messagingSenderId: "354700702496",
    appId: "1:354700702496:web:f41f81825ec8f446d79d45",
    measurementId: "G-5QGZSBNRQS"
  };

const GOOGLE_CLIENT_ID = "354700702496-pt335qcevivqrhk4hs1nm1o1groid4rc.apps.googleusercontent.com";

(function () {

  function byId(id) {
    return document.getElementById(id);
  }

  function firebaseConfigured() {
    return Boolean(
      firebaseConfig.apiKey &&
      firebaseConfig.authDomain &&
      firebaseConfig.projectId &&
      firebaseConfig.appId
    );
  }

  function googleClientConfigured() {
    return Boolean(
      GOOGLE_CLIENT_ID &&
      GOOGLE_CLIENT_ID.indexOf('TU_CLIENT_ID') === -1
    );
  }

  function googleClientMatchesFirebaseProject() {
    if (!googleClientConfigured()) {
      return false;
    }

    var projectNumber = String(
      firebaseConfig.messagingSenderId || ''
    ).trim();

    var clientId = String(
      GOOGLE_CLIENT_ID || ''
    ).trim();

    if (!projectNumber) {
      return true;
    }

    return clientId.indexOf(projectNumber + '-') === 0;
  }

  function setAvatar(image, fallback, url) {
    if (!image) {
      return;
    }

    if (url) {
      image.src = url;
      image.style.display = 'block';

      if (fallback) {
        fallback.style.display = 'none';
      }
    } else {
      image.removeAttribute('src');
      image.style.display = 'none';

      if (fallback) {
        fallback.style.display = 'flex';
      }
    }
  }

  function closeProfilePopover() {
    var popover = byId('googleProfilePopover');
    var trigger = byId('googleProfileTrigger');

    if (popover) {
      popover.classList.remove('active');
      popover.setAttribute('aria-hidden', 'true');
    }

    if (trigger) {
      trigger.setAttribute('aria-expanded', 'false');
    }
  }

  function showSetup(message) {
    closeProfilePopover();

    var signin = byId('googleSignInButton');
    var setup = byId('googleProfileSetup');
    var trigger = byId('googleProfileTrigger');

    if (signin) {
      signin.style.display = 'none';
    }

    if (trigger) {
      trigger.style.display = 'none';
    }

    if (setup) {
      setup.style.display = 'flex';

      var label = setup.querySelector('span');
      if (label && message) {
        label.textContent = message;
      }
    }
  }

  function showSignedOut() {
    closeProfilePopover();

    var signin = byId('googleSignInButton');
    var setup = byId('googleProfileSetup');
    var trigger = byId('googleProfileTrigger');

    if (trigger) {
      trigger.style.display = 'none';
    }

    if (!googleClientConfigured()) {
      if (signin) {
        signin.style.display = 'none';
      }

      if (setup) {
        setup.style.display = 'flex';
        var label = setup.querySelector('span');
        if (label) {
          label.textContent = 'Configurar Google';
        }
      }

      return;
    }

    if (!googleClientMatchesFirebaseProject()) {
      if (signin) {
        signin.style.display = 'none';
      }

      if (setup) {
        setup.style.display = 'flex';
        var mismatchLabel = setup.querySelector('span');
        if (mismatchLabel) {
          mismatchLabel.textContent = 'Client ID incorrecto';
        }
      }

      console.error(
        'CIAD Google: el OAuth Client ID no pertenece al mismo proyecto que Firebase. ' +
        'Usa el Web Client ID generado dentro del proyecto Firebase actual.'
      );

      return;
    }

    if (setup) {
      setup.style.display = 'none';
    }

    if (signin) {
      signin.style.display = 'flex';
    }

    waitForGoogleIdentity(0);
  }

  function showSignedIn(user) {
    var signin = byId('googleSignInButton');
    var setup = byId('googleProfileSetup');
    var trigger = byId('googleProfileTrigger');

    if (signin) {
      signin.style.display = 'none';
    }

    if (setup) {
      setup.style.display = 'none';
    }

    if (trigger) {
      trigger.style.display = 'flex';
    }

    var name = user.displayName || 'Cuenta Google';
    var email = user.email || 'Correo no disponible';
    var picture = user.photoURL || '';

    if (byId('googleProfileName')) {
      byId('googleProfileName').textContent = name;
    }

    if (byId('googleProfilePopoverName')) {
      byId('googleProfilePopoverName').textContent = name;
    }

    if (byId('googleProfileEmail')) {
      byId('googleProfileEmail').textContent = email;
    }

    setAvatar(
      byId('googleProfileAvatar'),
      byId('googleProfileAvatarFallback'),
      picture
    );

    var largeAvatar = byId('googleProfilePopoverAvatar');

    if (largeAvatar) {
      if (picture) {
        largeAvatar.src = picture;
        largeAvatar.style.display = 'block';
      } else {
        largeAvatar.removeAttribute('src');
        largeAvatar.style.display = 'none';
      }
    }
  }

  function publicUser(user) {
    if (!user) {
      return null;
    }

    return {
      uid: user.uid,
      displayName: user.displayName || '',
      email: user.email || '',
      photoURL: user.photoURL || ''
    };
  }

  function notifyAuthChanged(user) {
    window.dispatchEvent(
      new CustomEvent('ciad-auth-changed', {
        detail: {
          user: publicUser(user)
        }
      })
    );
  }

  if (!firebaseConfigured()) {
    document.addEventListener('DOMContentLoaded', function () {
      showSetup('Configurar Firebase');
    });

    console.warn(
      'CIAD Firebase: completa firebaseConfig antes de utilizar el inicio de sesión.'
    );

    return;
  }

  var app;
  var auth;
  var db;

  var explicitGoogleLoginInProgress = false;

  try {
    app = initializeApp(firebaseConfig);
    auth = getAuth(app);
    db = getFirestore(app);

    auth.languageCode = 'es';

    setPersistence(auth, browserLocalPersistence).catch(function (error) {
      console.warn(
        'CIAD Firebase: no se pudo establecer persistencia local.',
        error
      );
    });

    window.CIADFirebase = {
      app: app,
      auth: auth,
      db: db,
      getCurrentUser: function () {
        return auth.currentUser;
      }
    };

  } catch (error) {
    console.error('CIAD Firebase: error de inicialización.', error);

    document.addEventListener('DOMContentLoaded', function () {
      showSetup('Error de Firebase');
    });

    return;
  }

  async function syncUserProfile(user, registerLogin) {
    if (!user) {
      return;
    }

    var userRef = doc(db, 'users', user.uid);
    var snapshot = await getDoc(userRef);

    if (!snapshot.exists()) {
      await setDoc(userRef, {
        uid: user.uid,
        displayName: user.displayName || '',
        email: user.email || '',
        photoURL: user.photoURL || '',
        createdAt: serverTimestamp(),
        lastLogin: serverTimestamp()
      });

      console.log(
        'CIAD Firebase: usuario creado en Firestore:',
        user.uid
      );

      return;
    }

    var changes = {
      displayName: user.displayName || '',
      email: user.email || '',
      photoURL: user.photoURL || ''
    };

    if (registerLogin) {
      changes.lastLogin = serverTimestamp();
    }

    await updateDoc(userRef, changes);

    console.log(
      registerLogin
        ? 'CIAD Firebase: acceso registrado.'
        : 'CIAD Firebase: perfil sincronizado.'
    );
  }

  var googleInitialized = false;

  async function handleGoogleCredential(response) {
    if (!response || !response.credential) {
      return;
    }

    explicitGoogleLoginInProgress = true;

    try {
      var credential = GoogleAuthProvider.credential(
        response.credential
      );

      var result = await signInWithCredential(
        auth,
        credential
      );

      await syncUserProfile(result.user, true);

    } catch (error) {
      console.error(
        'CIAD Firebase: no se pudo completar el acceso con Google.',
        error
      );

      alert(
        'No se pudo completar el inicio de sesión con Google. Revisa la consola del navegador para ver el detalle.'
      );

    } finally {
      explicitGoogleLoginInProgress = false;
    }
  }

  function renderGoogleButton() {
    var host = byId('googleSignInButton');

    if (
      !host ||
      !googleClientConfigured() ||
      !googleClientMatchesFirebaseProject() ||
      !window.google ||
      !google.accounts ||
      !google.accounts.id
    ) {
      return false;
    }

    if (!googleInitialized) {
      google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: handleGoogleCredential,
        auto_select: false,
        cancel_on_tap_outside: true
      });

      googleInitialized = true;
    }

    host.innerHTML = '';

    google.accounts.id.renderButton(host, {
      type: 'icon',
      theme: 'outline',
      size: 'large',
      shape: 'circle'
    });

    return true;
  }

  function waitForGoogleIdentity(attempt) {
    attempt = attempt || 0;

    if (
      window.google &&
      google.accounts &&
      google.accounts.id
    ) {
      renderGoogleButton();
      return;
    }

    if (attempt < 60) {
      window.setTimeout(function () {
        waitForGoogleIdentity(attempt + 1);
      }, 100);
    } else {
      console.error(
        'CIAD: Google Identity Services no terminó de cargar.'
      );
    }
  }

  window.onGoogleLibraryLoad = function () {
    if (!auth.currentUser) {
      renderGoogleButton();
    }
  };

  document.addEventListener('DOMContentLoaded', function () {

    var trigger = byId('googleProfileTrigger');
    var popover = byId('googleProfilePopover');
    var signoutButton = byId('firebaseSignOutButton');
    var comments = byId('googleGoComments');

    if (trigger && popover) {
      trigger.addEventListener('click', function (event) {
        event.stopPropagation();

        var opening = !popover.classList.contains('active');

        popover.classList.toggle('active', opening);
        popover.setAttribute(
          'aria-hidden',
          opening ? 'false' : 'true'
        );
        trigger.setAttribute(
          'aria-expanded',
          opening ? 'true' : 'false'
        );
      });
    }

    if (popover) {
      popover.addEventListener('click', function (event) {
        event.stopPropagation();
      });
    }

    if (signoutButton) {
      signoutButton.addEventListener('click', async function () {
        signoutButton.disabled = true;

        try {
          await signOut(auth);

          if (
            window.google &&
            google.accounts &&
            google.accounts.id
          ) {
            google.accounts.id.disableAutoSelect();
          }

          closeProfilePopover();

        } catch (error) {
          console.error(
            'CIAD Firebase: no se pudo cerrar la sesión.',
            error
          );

        } finally {
          signoutButton.disabled = false;
        }
      });
    }

    if (comments) {
      comments.addEventListener('click', function () {
        closeProfilePopover();
      });
    }

    document.addEventListener('click', closeProfilePopover);

    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape') {
        closeProfilePopover();
      }
    });

  });

  onAuthStateChanged(auth, async function (user) {

    if (user) {
      showSignedIn(user);

      if (!explicitGoogleLoginInProgress) {
        try {
          await syncUserProfile(user, false);
        } catch (error) {
          console.error(
            'CIAD Firebase: sesión válida, pero Firestore rechazó o no pudo guardar el perfil.',
            error
          );
        }
      }

    } else {
      showSignedOut();
    }

    notifyAuthChanged(user);
  });

})();
