(function(){
  function norm(s){return (s||'').toLowerCase().replace(/^categoria-/,'').replace(/\.html$/,'').replace(/-y-/g,'-').replace(/[^a-z0-9]/g,'');}
  function clave(p){p=p.replace(/\/+$/,'')||'/'; if(p==='/'||p==='/p/inicio.html'){return '__inicio__';} if(p.indexOf('/p/')===0){return norm(p.split('/p/')[1]);} return null;}
  function marcar(){
    var claves=[]; var actual=clave(location.pathname);
    if(actual){claves.push(actual);} else if(!document.querySelector('.vista-notas')){ /* en Todas las notas no hay sección actual */
      document.querySelectorAll('.post-outer a[href*="/search/label/"], .post a[href*="/search/label/"]').forEach(function(a){
        var m=decodeURIComponent(a.getAttribute('href')||'').match(/\/search\/label\/([^?#]+)/);
        if(m && m[1].toLowerCase().indexOf('categoria-')===0){claves.push(norm(m[1]));}
      });
    }
    document.querySelectorAll('.nav-links a, .mobile-menu a').forEach(function(a){
      var u; try{u=new URL(a.getAttribute('href')||'',location.href);}catch(e){return;}
      if(u.host!==location.host){return;}
      var k=clave(u.pathname); if(k && claves.indexOf(k)>-1){a.classList.add('nav-actual');a.setAttribute('aria-current','page');}
    });
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',marcar);}else{marcar();}
})();
