// US7: visor de la galería de la nota (clic en una miniatura → imagen grande con anterior/siguiente)
(function () {
  var visor, imagen, contador, anterior, siguiente;
  var fotos = [];
  var actual = 0;

  function crearVisor() {
    visor = document.createElement('div');
    visor.className = 'visor-galeria';
    visor.setAttribute('role', 'dialog');
    visor.setAttribute('aria-label', 'Galería de imágenes');
    visor.innerHTML =
      '<button type="button" class="visor-cerrar" aria-label="Cerrar">×</button>' +
      '<button type="button" class="visor-anterior" aria-label="Imagen anterior">‹</button>' +
      '<img alt=""/>' +
      '<button type="button" class="visor-siguiente" aria-label="Imagen siguiente">›</button>' +
      '<p class="visor-contador"></p>';
    document.body.appendChild(visor);

    imagen = visor.querySelector('img');
    contador = visor.querySelector('.visor-contador');
    anterior = visor.querySelector('.visor-anterior');
    siguiente = visor.querySelector('.visor-siguiente');

    visor.querySelector('.visor-cerrar').addEventListener('click', cerrar);
    anterior.addEventListener('click', function () { mostrar(actual - 1); });
    siguiente.addEventListener('click', function () { mostrar(actual + 1); });
    visor.addEventListener('click', function (e) { if (e.target === visor) cerrar(); });
  }

  function mostrar(indice) {
    actual = (indice + fotos.length) % fotos.length;
    var foto = fotos[actual];
    var miniatura = foto.querySelector('img');
    imagen.src = foto.getAttribute('href');
    imagen.alt = miniatura ? miniatura.alt : '';
    contador.textContent = (actual + 1) + ' / ' + fotos.length;
    anterior.hidden = siguiente.hidden = fotos.length < 2;
  }

  function cerrar() {
    visor.classList.remove('abierto');
    imagen.src = '';
    document.body.style.overflow = '';
  }

  document.addEventListener('click', function (e) {
    var foto = e.target.closest('.articulo-galeria-foto');
    if (!foto) return;
    e.preventDefault();
    fotos = Array.prototype.slice.call(foto.closest('.articulo-galeria').querySelectorAll('.articulo-galeria-foto'));
    if (!visor) crearVisor();
    mostrar(fotos.indexOf(foto));
    visor.classList.add('abierto');
    document.body.style.overflow = 'hidden';
  });

  document.addEventListener('keydown', function (e) {
    if (!visor || !visor.classList.contains('abierto')) return;
    if (e.key === 'Escape') cerrar();
    if (e.key === 'ArrowLeft') mostrar(actual - 1);
    if (e.key === 'ArrowRight') mostrar(actual + 1);
  });
})();
