/* Panel CIAD: encuadre de las tarjetas cuando la imagen no se recortó (un GIF conserva su animación).
   La nota trae la imagen como ...#ciad=x,y,z: aquí se le pone object-position y acercamiento, como en el panel. */
(function () {
  function ajustar(img) {
    var m = (img.getAttribute('src') || '').match(/#ciad=(\d+),(\d+),(\d+)/);
    if (!m) return;
    img.style.objectFit = 'cover';
    img.style.objectPosition = m[1] + '% ' + m[2] + '%';
    img.style.transformOrigin = m[1] + '% ' + m[2] + '%';
    img.style.scale = String(m[3] / 100);
  }
  function revisar(nodo) {
    if (nodo.nodeType !== 1) return;
    if (nodo.tagName === 'IMG') ajustar(nodo);
    else if (nodo.querySelectorAll) nodo.querySelectorAll('img').forEach(ajustar);
  }
  new MutationObserver(function (cambios) {
    cambios.forEach(function (c) {
      if (c.type === 'attributes') ajustar(c.target);
      else c.addedNodes.forEach(revisar);
    });
  }).observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ['src'] });
  revisar(document.body);
})();

// Secciones visibles (Panel CIAD > Páginas): una página en borrador no sale en el menú ni en «Todas las notas»
(function () {
  var CLAVE = 'ciad-paginas-ocultas';
  function enlaces() { return document.querySelectorAll('.nav-links a, .mobile-menu a, .grupo-notas[data-pagina]'); }
  function ruta(el) { return el.getAttribute('data-pagina') || el.pathname; }
  function aplicar(ocultas) {
    enlaces().forEach(function (a) {
      var caja = a.closest('li, .grupo-notas') || a, oculta = ocultas.indexOf(ruta(a)) !== -1;
      caja.style.display = oculta ? 'none' : '';
      var indice = caja.id && document.querySelector('.notas-indice a[href="#' + caja.id + '"]');
      if (indice) indice.style.display = oculta ? 'none' : '';
    });
  }
  // Lo último conocido se aplica de inmediato (sin parpadeo); el feed lo confirma
  try { aplicar(JSON.parse(localStorage.getItem(CLAVE)) || []); } catch (e) {}
  fetch('/feeds/pages/default?alt=json&max-results=100').then(function (r) { return r.json(); }).then(function (d) {
    var vivas = (d.feed.entry || []).map(function (e) {
      var alt = (e.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
      return alt ? new URL(alt.href).pathname : '';
    });
    var ocultas = [];
    enlaces().forEach(function (a) {
      var r = ruta(a);
      if (/^\/p\/.+\.html$/.test(r) && vivas.indexOf(r) === -1 && ocultas.indexOf(r) === -1) ocultas.push(r);
    });
    try { localStorage.setItem(CLAVE, JSON.stringify(ocultas)); } catch (e) {}
    aplicar(ocultas);
  }).catch(function () {});
})();
